#!/bin/bash
# Script to automatically fix no-unused-vars ESLint errors
# Generated by Claude Code based on Gemini's correction pattern

set -e

echo "🔧 Fixing ESLint no-unused-vars errors..."

# Backup directory
BACKUP_DIR="/tmp/archon-lint-backup-$(date +%s)"
mkdir -p "$BACKUP_DIR"

# Function to backup and fix a file
fix_file() {
    local file="$1"
    shift
    local patterns=("$@")

    if [ ! -f "$file" ]; then
        echo "⚠️  File not found: $file"
        return
    fi

    # Backup
    cp "$file" "$BACKUP_DIR/$(basename $file)"

    # Apply fixes
    for pattern in "${patterns[@]}"; do
        sed -i.bak "$pattern" "$file"
        rm -f "${file}.bak"
    done

    echo "✅ Fixed: $file"
}

