else
    echo ""
    echo "❌ FAILED! Restoring backup..."
    # Restore backup
    for backup in "$BACKUP_DIR"/*; do
        filename=$(basename "$backup")
        find . -name "$filename" -type f -exec cp "$backup" {} \;
    done
    echo "⚠️  Backup restored. Manual fixing required."
    exit 1
fi
